module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    input  logic dig,
    output logic walk_left,
    output logic walk_right,
    output logic aaah,
    output logic digging
);

    typedef enum logic [2:0] {
        S_WALK_L   = 3'd0,
        S_WALK_R   = 3'd1,
        S_DIG_L    = 3'd2,
        S_DIG_R    = 3'd3,
        S_FALL_L   = 3'd4,
        S_FALL_R   = 3'd5,
        S_SPLATTER = 3'd6
    } state_t;

    state_t state, next_state;
    logic [5:0] fall_count;

    // Fall counter logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            fall_count <= '0;
        end else if (ground == 1'b0) begin
            if (fall_count < 6'd32)
                fall_count <= fall_count + 1'b1;
        end else begin
            fall_count <= '0;
        end
    end

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= S_WALK_L;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic (Precedence: Fall > Dig > Switch)
    always_comb begin
        next_state = state;

        case (state)
            S_SPLATTER: begin
                next_state = S_SPLATTER;
            end

            S_WALK_L: begin
                if (ground == 1'b0) begin
                    next_state = S_FALL_L;
                end else if (dig == 1'b1) begin
                    next_state = S_DIG_L;
                end else if (bump_left && bump_right) begin
                    next_state = S_WALK_R;
                end else if (bump_left) begin
                    next_state = S_WALK_R;
                end else if (bump_right) begin
                    next_state = S_WALK_L;
                end
            end

            S_WALK_R: begin
                if (ground == 1'b0) begin
                    next_state = S_FALL_R;
                end else if (dig == 1'b1) begin
                    next_state = S_DIG_R;
                end else if (bump_left && bump_right) begin
                    next_state = S_WALK_L;
                end else if (bump_right) begin
                    next_state = S_WALK_L;
                end else if (bump_left) begin
                    next_state = S_WALK_R;
                end
            end

            S_DIG_L: begin
                if (ground == 1'b0) begin
                    next_state = S_FALL_L;
                end
            end

            S_DIG_R: begin
                if (ground == 1'b0) begin
                    next_state = S_FALL_R;
                end
            end

            S_FALL_L: begin
                if (ground == 1'b1) begin
                    if (fall_count > 6'd20) begin
                        next_state = S_SPLATTER;
                    end else begin
                        next_state = S_WALK_L;
                    end
                end
            end

            S_FALL_R: begin
                if (ground == 1'b1) begin
                    if (fall_count > 6'd20) begin
                        next_state = S_SPLATTER;
                    end else begin
                        next_state = S_WALK_R;
                    end
                end
            end

            default: next_state = S_WALK_L;
        endcase
    end

    // Output logic
    always_comb begin
        walk_left  = 1'b0;
        walk_right = 1'b0;
        aaah       = 1'b0;
        digging    = 1'b0;

        case (state)
            S_WALK_L: begin
                walk_left = 1'b1;
            end
            S_WALK_R: begin
                walk_right = 1'b1;
            end
            S_DIG_L: begin
                walk_left = 1'b1;
                digging   = 1'b1;
            end
            S_DIG_R: begin
                walk_right = 1'b1;
                digging    = 1'b1;
            end
            S_FALL_L: begin
                walk_left = 1'b1;
                aaah      = 1'b1;
            end
            S_FALL_R: begin
                walk_right = 1'b1;
                aaah       = 1'b1;
            end
            S_SPLATTER: begin
                // All outputs zero
            end
            default: ;
        endcase
    end

endmodule

